WITH kept_keys AS (SELECT id, order_id FROM order_items INTERSECT ALL SELECT id, order_id FROM order_items WHERE quantity BETWEEN 4 AND 5), kept_rows AS (SELECT s.* FROM order_items s INNER JOIN kept_keys k ON s.id = k.id AND s.order_id = k.order_id) SELECT s.id, s.order_id, s.quantity, s.unit_price, (SELECT SUM(o2.quantity) FROM order_items o2 WHERE o2.order_id = s.order_id) AS sum_order_item_quantity FROM kept_rows s ORDER BY order_id DESC NULLS LAST;
